using NetArchTest.Rules;

namespace PaymentAuthorization.IntegrationTest.Architecture;

/// <summary>
/// Layer discipline enforced by CI. Each rule is a static scan, never a behavioral test.
/// Failure messages list the violating types so review isn't needed to find them.
/// </summary>
public sealed class ArchitectureTests
{
    private static readonly Assembly DomainAssembly = typeof(Domain.Money).Assembly;
    private static readonly Assembly ApplicationAssembly = typeof(Application.AuthorizePayment).Assembly;
    private static readonly Assembly InfrastructureAssembly = typeof(Infrastructure.FileSystemReceiptStore).Assembly;

    // ----- Project references: each project references only its inner neighbour -----

    [Theory]
    [InlineData("PaymentAuthorization.Domain")]
    [InlineData("PaymentAuthorization.Application", "PaymentAuthorization.Domain")]
    [InlineData("PaymentAuthorization.Infrastructure", "PaymentAuthorization.Application")]
    public void Project_ReferencesOnlyItsInnerNeighbour(string project, params string[] allowed)
    {
